from test_bufftap import test, ROOT
from test_cleanse import S
from test_revive import R
from test_helpers import solo
from test_manual_thanks_12612 import manual
from test_nearby import setup as N

for answer in ['return nil,nil',"error('unavailable')",'return {secret=true},false','return false,false']:
    test('Cleanse refuses unreadable or refused usability: '+answer,S+"debuff('player',8552,'Curse of Weakness','Curse',60); local old=C_Spell.IsSpellUsable; C_Spell.IsSpellUsable=function(id) if id==2782 then "+answer+" end return old(id) end; refresh(); assert(not (B.action and B.action.source=='cleanse'))")
    test('Revive refuses unreadable or refused usability: '+answer,R+"local a=B:SelectRevive(); assert(a); C_Spell.IsSpellUsable=function() "+answer+" end; assert(not B:ValidateRevive(a)); assert(not B:SelectRevive())")
for answer in ['return nil',"error('unavailable')",'return {secret=true}','return {startTime=0,duration=0}', 'return {startTime=0,duration=0,isEnabled=false}', 'return {startTime={secret=true},duration=0,isEnabled=true}', 'return {startTime=0,duration=0,isEnabled=true,isActive={secret=true}}','return {startTime=now,duration=1,isEnabled=true,isActive=true}', 'return {startTime=now,duration=1,isEnabled=true,isActive=true,isOnGCD=true}']:
    test('Cleanse refuses unverified or active cooldown: '+answer,S+"debuff('player',8552,'Curse of Weakness','Curse',60); C_Spell.GetSpellCooldown=function() "+answer+" end; refresh(); assert(not (B.action and B.action.source=='cleanse'))")
test('Cleanse rejects a new unusable state at main PreClick',S+"debuff('player',8552,'Curse of Weakness','Curse',60); refresh(); assert(B.action.source=='cleanse'); C_Spell.IsSpellUsable=function() return nil end; B.button.scripts.PreClick(B.button,'LeftButton',true); assert(not B.action and not B.button.attrs.type1)")
test('Revive rejects a new missing cooldown at main PreClick',R+"refresh(); assert(B.action.source=='revive'); C_Spell.GetSpellCooldown=function() return nil end; B.button.scripts.PreClick(B.button,'LeftButton',true); assert(not B.action and not B.button.attrs.type1)")

C=S+"B.db.buffs.motw=false; B.db.buffs.thorns=false; B.db.showOutOfRange=true; local inRange=false; C_Spell.IsSpellInRange=function(id,u) if id==2782 and u~='player' then return inRange end return true end; "
test('Party cleanse gets a greyed notice and recovers through range heartbeat',C+"debuff('party1',8552,'Curse of Weakness','Curse',60); refresh(); assert(B.action and B.action.source=='range' and B.action.target=='party1' and not B.button.attrs.type1); assert(B.rangeBlockedActions[1].source=='cleanse'); inRange=true; advance(1.3); assert(B.action and B.action.source=='cleanse' and B.action.target=='party1'); B.button.scripts.PreClick(B.button,'LeftButton',true); assert(B.button.attrs.spell==2782)")
test('Friendly-target cleanse gets an independent greyed notice',C+"UnitInParty=function() return false end; UnitInRaid=function() return nil end; UnitIsPlayer=function() return true end; debuff('target',8552,'Curse of Weakness','Curse',60); refresh(); assert(B.action and B.action.source=='range' and B.action.target=='target')")
test('Dismiss grey cleanse leaves the real cast available on return',C+"B.db.helperDismiss=true; debuff('party1',8552,'Curse of Weakness','Curse',60); refresh(); assert(B.action.source=='range'); B:DismissHelper(B.action); refresh(); assert(not B.action); inRange=true; advance(1.3); assert(B.action and B.action.source=='cleanse')")
test('Returning range cannot revive a stale cleanse debuff',C+"debuff('party1',8552,'Curse of Weakness','Curse',60); refresh(); debuffs.party1={}; B.events.scripts.OnEvent(nil,'UNIT_AURA','party1'); inRange=true; advance(1.3); assert(not (B.action and B.action.source=='cleanse'))")
test('Nearby nameplate range probe still never becomes a main notice',N+"local B=BuffTap; local inside=false; C_Spell.IsSpellInRange=function(id,u) if u=='nameplate1' then return inside end return true end; B.db.showOutOfRange=true; refresh(); assert(not B.action and not B.rangeBlocked and #B.rangeBlockedActions==0); assert(B.timers['nearby-range']); inside=true; advance(1.3); assert(B.action and B.action.nearby)")

grp=solo+"BuffTap.db.helperThanksOutsiders=true; IsInGroup=function() return true end; "
test('Unknown raid state blocks an actual raid giver',grp+"IsInRaid=function() return nil end; local oe,og=UnitExists,UnitGUID; UnitExists=function(u) return u=='raid3' or oe(u) end; UnitGUID=function(u) if u=='raid3' then return og('target') end return og(u) end; assert(BuffTap:ThanksInGroup(og('target'))==nil); received(1459,'target'); assert(#emotes==0)")
test('Missing expected party token blocks outsider thanks',grp+"GetNumSubgroupMembers=function() return 1 end; UnitExists=function(u) return u=='player' or u=='target' end; assert(BuffTap:ThanksInGroup(UnitGUID('target'))==nil); received(1459,'target'); assert(#emotes==0)")
for answer in ['return nil','return 0','return 5','return 1.5',"error('unavailable')",'return {secret=true}']:
    test('Invalid party count cannot authorize outsider thanks: '+answer,grp+"GetNumSubgroupMembers=function() "+answer+" end; assert(BuffTap:ThanksInGroup(UnitGUID('target'))==nil); received(1459,'target'); assert(#emotes==0)")
test('Complete raid roster permits a genuine outsider',grp+"IsInRaid=function() return true end; GetNumGroupMembers=function() return 3 end; local oe=UnitExists; UnitExists=function(u) return u:match('^raid[123]$')~=nil or oe(u) end; assert(BuffTap:ThanksInGroup(UnitGUID('target'))==false); received(1459,'target'); assert(#emotes==1)")
test('Complete raid roster still never thanks its member',grp+"IsInRaid=function() return true end; GetNumGroupMembers=function() return 3 end; local oe=UnitExists; UnitExists=function(u) return u:match('^raid[123]$')~=nil or oe(u) end; assert(BuffTap:ThanksInGroup(UnitGUID('raid3'))==true); received(1459,'raid3'); assert(#emotes==0)")
test('Roster count change during lookup fails closed',grp+"local calls=0; GetNumSubgroupMembers=function() calls=calls+1; return calls==1 and 2 or 1 end; assert(BuffTap:ThanksInGroup(UnitGUID('target'))==nil)")
test('Incomplete roster blocks manual thanks offer',manual+"B.db.helperThanksOutsiders=true; IsInGroup=function() return true end; IsInRaid=function() return nil end; B:OfferManualThanks(a); assert(not (B.manualThanksQueue and B.manualThanksQueue[a.casterGUID]))")
test('Roster uncertainty before manual send drops that offer',manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; assert(e); B.db.helperThanksOutsiders=true; IsInGroup=function() return true end; IsInRaid=function() return nil end; assert(not B:SendManualThanks(e) and #sent==0 and not B.manualThanksQueue[a.casterGUID])")

test('Restore cancels dismissal timers without unrelated timers',"local B=BuffTap; B.db.helperDismissMinutes=10; B:DismissHelper(B.action); local key=B:HelperKey(B.action); B:StartTimer('review-unrelated',600,function() end); assert(B.timers['dismiss-'..key]); B:RestoreHelpers(); assert(not B.timers['dismiss-'..key] and B.timers['review-unrelated'] and not next(B.helperDismissed) and not next(B.helperDismissUntil))")
test('Zone reset cancels old dismissal timers',"local B=BuffTap; B.db.helperDismissMinutes=10; B:DismissHelper(B.action); local key=B:HelperKey(B.action); B:HelperEvent('ZONE_CHANGED_NEW_AREA'); assert(not B.timers['dismiss-'..key] and not next(B.helperDismissUntil))")
test('Nearby cleanup removes expired history and preserves active cooldowns',"local B=BuffTap; local windows={favors=300,favorGiven=300,favorBumped=1800,nearbyRequested=180,socialPresent=60,socialAlerted=3600,socialPending=30}; for field,age in pairs(windows) do B[field]={old=now-age-1,recent=now-1,bad='invalid'} end; B.nearbyHistoryPrunedAt=nil; B:PruneNearbyHistory(); for field in pairs(windows) do assert(not B[field].old and not B[field].bad and B[field].recent==now-1,field) end")
test('Nearby cleanup is throttled on repeated activity',"local B=BuffTap; B.favors={old=now-400}; B:PruneNearbyHistory(); B.favors.old=now-400; B:PruneNearbyHistory(); assert(B.favors.old); now=now+61; B:PruneNearbyHistory(); assert(not B.favors.old)")
